import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const S=JSON.parse('{"title":"隐藏命令与测试桩 — 调试面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/hidden-commands.md","filePath":"zh/manual/hidden-commands.md"}'),r={name:"zh/manual/hidden-commands.md"};function a(s,t,h,l,i,n){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="隐藏命令与测试桩-—-调试面" tabindex="-1">隐藏命令与测试桩 — 调试面 <a class="header-anchor" href="#隐藏命令与测试桩-—-调试面" aria-label="Permalink to &quot;隐藏命令与测试桩 — 调试面&quot;">​</a></h1><p>284 个已注册程序中约三分之一是<strong>测试桩</strong>：主体从 v2.2.0 shell 迁移而来，现在经由 L1SVC 桥接提供服务，或以平坦 ring-3 探针形式链接。它们都是普通的注册表命令 —— 在 <code>ush&gt;</code> 提示符下输入名字并按 ENTER 即可；无需特殊运行器， 除非特别说明也无需 flag。<code>help</code> 中没有任何标记表明它们是测试： 它们与 <code>ls</code> 或 <code>ping</code> 一样出现在 A-Z 列表中。</p><p>全仓扫描统计出 <strong>约 93 个测试味程序</strong>：69 个 <code>*test*</code> 命名的 目录应用外加 24 个平坦单文件探针（边界是模糊的 —— <code>hello</code>、<code>loop</code>、<code>badapp</code>、<code>p0leak</code> 是作业测试用作目标的平坦工具 探针）。本页逐一列出，按其演练的内容分组，附运行方法与健康 运行的输出。</p><blockquote><p><strong>安全性</strong>：除标注项外，此处一切均为只读或自包含 <strong>除</strong> 标注项之外：<code>fs_mount_test</code>（格式化设备）、四个电源路径 探针（可能终结会话）、<code>crashtest</code>（故意让内核 panic —— 这就是测试本身）、<code>stackovf</code>/<code>badapp</code>/<code>sigsegv_test</code>（故意 自杀）。</p></blockquote><h2 id="它们如何接线" tabindex="-1">它们如何接线 <a class="header-anchor" href="#它们如何接线" aria-label="Permalink to &quot;它们如何接线&quot;">​</a></h2><ul><li><strong>目录桩</strong>（<code>ocos/l1apps/&lt;name&gt;/main.c</code>）是标准 <code>l1svc_main()</code> 封装：argv 被连接成一条 256 字节行并发送给 所属服务 op；服务运行真正的测试主体，打印文本经输出捕获 返回。</li><li><strong>平坦探针</strong>（<code>ocos/l1apps/&lt;name&gt;.c|.asm</code>，标签 <code>l1</code>）是真实 的 ring-3 程序，自己发起原始系统调用 —— 它们直接演练 内核面并打印各自的判定。</li><li>判定行统一为 <code>PASS</code> / <code>FAIL</code> / <code>SKIPPED</code>（硬件缺失时为 <code>(honest skip)</code> / <code>(honest FAIL)</code> —— 那是<em>正确</em>的结果， 不是失败）。</li></ul><hr><h2 id="a-类-—-目录测试桩-按家族" tabindex="-1">A 类 — 目录测试桩，按家族 <a class="header-anchor" href="#a-类-—-目录测试桩-按家族" aria-label="Permalink to &quot;A 类 — 目录测试桩，按家族&quot;">​</a></h2><h3 id="ota-更新管线-12" tabindex="-1">OTA / 更新管线（12） <a class="header-anchor" href="#ota-更新管线-12" aria-label="Permalink to &quot;OTA / 更新管线（12）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>ab_partition_test</code></td><td>A/B 标志文件协议与槽位检测</td><td><code>ab_partition_test</code></td><td>逐项 OK 行 + 最终 PASS</td></tr><tr><td><code>checkupdate_test</code></td><td>checkupdate 负面固定件（拒绝 <code>ftp://</code> 前缀、拒绝损坏 JSON、128 字节缓冲拒绝超长变更、缺失 URL）</td><td><code>checkupdate_test</code></td><td>每个恶意固定件 <code>(correctly rejected) =&gt; PASS</code></td></tr><tr><td><code>config_test</code></td><td>配置后端（读/写/恢复、CRC32 损坏、截断、ustar 坏校验和拒绝）</td><td><code>config_test</code></td><td>PASS 块</td></tr><tr><td><code>update_check_test</code></td><td>check 步骤单元测试</td><td><code>update_check_test</code></td><td>PASS</td></tr><tr><td><code>update_download_test</code></td><td>download 步骤单元测试</td><td><code>update_download_test</code></td><td>PASS</td></tr><tr><td><code>update_install_test</code></td><td>install 步骤单元测试</td><td><code>update_install_test</code></td><td>PASS</td></tr><tr><td><code>update_local_test</code></td><td>离线包安装（<code>--local</code> 路径）</td><td><code>update_local_test</code></td><td>PASS</td></tr><tr><td><code>update_pkg_test</code></td><td>包解析（gzip/tar/sha256：损坏 CRC32、截断流、坏 ustar 校验和、错误 sha256 全部被拒）</td><td><code>update_pkg_test</code></td><td>各拒绝 PASS</td></tr><tr><td><code>update_rollback_test</code></td><td>回滚标志清除</td><td><code>update_rollback_test</code></td><td>PASS；<code>set_boot(X) rejected</code></td></tr><tr><td><code>update_status_test</code></td><td>status op</td><td><code>update_status_test</code></td><td>PASS</td></tr><tr><td><code>update_verify_test</code></td><td>SHA256 校验</td><td><code>update_verify_test</code></td><td>PASS</td></tr><tr><td><code>real_update_test</code></td><td>针对在线源的完整真实流程（check→download→verify→install）</td><td><code>real_update_test</code></td><td>PASS，或如实的已是最新</td></tr></tbody></table><p>支撑工具：<code>tools/make_update_pkg.sh</code>（包构建器）和 <code>tools/fix1_checkupdate_e2e.py</code>（E2E）。</p><h3 id="块-存储-8" tabindex="-1">块 / 存储（8） <a class="header-anchor" href="#块-存储-8" aria-label="Permalink to &quot;块 / 存储（8）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>ahci_test</code></td><td>AHCI 端口 IDENTIFY + I/O</td><td><code>ahci_test</code></td><td>每端口 PASS；无控制器 → 如实跳过</td></tr><tr><td><code>nvme_test</code></td><td>NVMe admin/io 队列</td><td><code>nvme_test</code></td><td>PASS</td></tr><tr><td><code>ata_dma_test</code></td><td>ATA DMA 传输</td><td><code>ata_dma_test</code></td><td>PASS</td></tr><tr><td><code>virtio_blk_test</code></td><td>virtio-blk 环 I/O</td><td><code>virtio_blk_test</code></td><td>PASS</td></tr><tr><td><code>disk_rw_test</code></td><td>裸扇区读/写往返</td><td><code>disk_rw_test &lt;device&gt;</code></td><td>数据比对 PASS</td></tr><tr><td><code>partition_test</code></td><td>MBR/GPT 扫描</td><td><code>partition_test &lt;device&gt;</code></td><td>表转储 + PASS</td></tr><tr><td><code>fs_mount_test</code></td><td>格式化后挂载 — <strong>destructive</strong></td><td><code>fs_mount_test &lt;device&gt;</code></td><td>格式化该设备，然后挂载：PASS</td></tr><tr><td><code>real_hw_test</code></td><td>真实硬件磁盘 + NIC 小节</td><td><code>real_hw_test</code></td><td>每设备 PASS</td></tr></tbody></table><h3 id="nic-驱动-10" tabindex="-1">NIC 驱动（10） <a class="header-anchor" href="#nic-驱动-10" aria-label="Permalink to &quot;NIC 驱动（10）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>e1000e_test</code>, <code>igb_test</code>, <code>ixgbe_test</code>, <code>bcm57xx_test</code>, <code>rtl810x_test</code>, <code>rtl8125_test</code>, <code>rtl8139_test</code>, <code>rtl8168_test</code> (8)</td><td>每驱动寄存器探针 + 环回</td><td><code>&lt;name&gt;_test</code></td><td>PASS，或无卡时如实的 <code>init failed</code></td></tr><tr><td><code>nic_rw_test</code></td><td>经块无关 API 的 NIC 帧环回</td><td><code>nic_rw_test</code></td><td>PASS；无卡时 <code>no NICs registered =&gt; SKIP</code></td></tr><tr><td><code>other_nic_test</code></td><td>尽力而为的家族（3c59x / nForce / Atheros AR81xx / Marvell）</td><td><code>other_nic_test</code></td><td>PASS 或如实跳过</td></tr></tbody></table><h3 id="音频-8" tabindex="-1">音频（8） <a class="header-anchor" href="#音频-8" aria-label="Permalink to &quot;音频（8）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>hda_test</code> / <code>ac97_test</code> / <code>sb16_test</code> / <code>es1370_test</code> / <code>virtio_snd_test</code> / <code>usb_audio_test</code> (6)</td><td>每驱动播放自测</td><td>裸调用</td><td>PASS；驱动缺失 → 如实跳过</td></tr><tr><td><code>audio_rw_test</code></td><td>PCM 读/写环回</td><td><code>audio_rw_test</code></td><td>PASS；<code>no sound cards registered =&gt; SKIPPED</code></td></tr><tr><td><code>sample_rate_test</code></td><td>采样率重编程精度</td><td><code>sample_rate_test</code></td><td>PASS；非法速率 <code>(unsupported, correctly rejected) =&gt; PASS</code>；QEMU 的 hda 模型在 44.1 kHz 上死循环 —— 已报告为已知模型限制，真实硬件编程正常</td></tr></tbody></table><h3 id="usb-7" tabindex="-1">USB（7） <a class="header-anchor" href="#usb-7" aria-label="Permalink to &quot;USB（7）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>usb_core_test</code></td><td>主机控制器核心（枚举步骤）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>usb_hotplug_test</code></td><td>插入/拔出路径</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>usb_hub_test</code></td><td>hub 枚举</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>usb_kbd_test</code></td><td>HID 键盘</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>usb_mouse_test</code></td><td>HID 鼠标</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>usb_serial_test</code></td><td>CDC-serial</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>usb_storage_test</code></td><td>MSC 读/写（<code>blk_read_sectors</code>，数据比对）</td><td>裸调用</td><td>PASS</td></tr></tbody></table><h3 id="遗留端口-摄像头-6" tabindex="-1">遗留端口 / 摄像头（6） <a class="header-anchor" href="#遗留端口-摄像头-6" aria-label="Permalink to &quot;遗留端口 / 摄像头（6）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>uvctest</code></td><td>UVC 采集（MJPEG）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>scsitest</code></td><td>SCSI/LSI 53C895A 扫描</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>gameporttest</code></td><td>游戏端口摇杆</td><td>裸调用</td><td>PASS 或 <code>no stick (timeout)</code> 如实跳过</td></tr><tr><td><code>paralleltest</code></td><td>并行端口 SPP 字节</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>irtest</code></td><td>IR 解码（NEC/RC5/RC6/SIRC，损坏帧拒绝）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>touchtest</code></td><td>触摸板描述符解析 + TAP/SCROLL/PINCH/SWIPE 手势</td><td>裸调用</td><td>每手势 PASS</td></tr></tbody></table><h3 id="电源路径-4-—-可能终结会话" tabindex="-1">电源路径（4）— 可能终结会话 <a class="header-anchor" href="#电源路径-4-—-可能终结会话" aria-label="Permalink to &quot;电源路径（4）— 可能终结会话&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>poweroff_test</code></td><td>关机端口链</td><td>裸调用（向导先警告 + 确认）</td><td>机器仍在运行则 <code>power-off NOT observed : FAIL</code>；在真实硬件上会话直接结束</td></tr><tr><td><code>suspend_test</code></td><td>S3 挂起/恢复</td><td>裸调用</td><td>失败时 <code>S3 resume failed.</code>；恢复 = 成功</td></tr><tr><td><code>halt_test</code></td><td>halt 路径</td><td>裸调用</td><td>未观察到活体 halt → FAIL/SKIP 判定</td></tr><tr><td><code>reboot_test</code></td><td>重启路径</td><td>裸调用</td><td>机器重启（会话结束）</td></tr></tbody></table><h3 id="显示-cjk-5" tabindex="-1">显示 / CJK（5） <a class="header-anchor" href="#显示-cjk-5" aria-label="Permalink to &quot;显示 / CJK（5）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>chinesetest</code></td><td>CJK 字体 + 编码测试组</td><td>裸调用</td><td>PASS（无 <code>FAILURES PRESENT</code>）</td></tr><tr><td><code>font-test</code></td><td>字体渲染器 + 负面固定件（区/位/槽/前导/截断/代理项/超长/C1 拒绝）</td><td>裸调用</td><td>每个恶意输入 <code>(rejected) =&gt; PASS</code></td></tr><tr><td><code>encoding-test</code></td><td>GB2312↔UTF-8 编解码器</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>ime-test</code></td><td>IME 引擎 + 会话（词组、翻页、数字选择协议断言）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>tui-test</code></td><td>TUI 渲染/窗口/输入/IME + 崩溃防护（<code>panic -&gt; -1000</code> 遏制）</td><td>裸调用</td><td>判定块 PASS</td></tr></tbody></table><h3 id="内核核心-诊断-网络-加密-17-12" tabindex="-1">内核核心 / 诊断 / 网络 / 加密（17 + 12） <a class="header-anchor" href="#内核核心-诊断-网络-加密-17-12" aria-label="Permalink to &quot;内核核心 / 诊断 / 网络 / 加密（17 + 12）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>测试内容</th><th>运行</th><th>健康输出</th></tr></thead><tbody><tr><td><code>memtest</code></td><td>内存服务测试组</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>heaptest</code></td><td>堆压力 + 回绕防护（<code>wrap size 0xFF...F1 was served</code> 必须不得被如实服务）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>heapbounds</code></td><td>堆边界条件</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>fstest</code></td><td>VFS 套件，含 BUG 编号回归行（BUG-0178/0179/0180/0182/0184/0061）</td><td>裸调用</td><td>每条 BUG 行 PASS</td></tr><tr><td><code>vmtest</code></td><td>VMM 单元测试</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>vmkernelpt</code></td><td>内核页表不变量</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>vmmap</code></td><td>地址空间映射遍历</td><td>裸调用</td><td>转储 + PASS</td></tr><tr><td><code>cr3test</code></td><td>CR3 审计</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>pftest</code></td><td>缺页处理计数器</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>pmmrace</code></td><td>PMM 分配竞态检测器</td><td>裸调用</td><td>PASS（无 <code>FAIL (race)</code>）</td></tr><tr><td><code>irqabitest</code></td><td>IRQ 亲和性</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>msitest</code></td><td>MSI 中断 — <strong>真实注入</strong>，见下文</td><td>裸调用</td><td><code>msitest: PASS</code></td></tr><tr><td><code>timer</code></td><td>定时器节拍</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>synctest</code></td><td>同步原语</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>multi</code></td><td>多核唤醒（3 个交错任务）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>spawn</code></td><td>后台孵化</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>exc</code></td><td>异常报告状态（#UD/#PF/#BP 计数器）</td><td>裸调用</td><td>计数器符合预期</td></tr><tr><td><code>crashtest</code></td><td>崩溃路径注入 — 8 种模式</td><td><code>crashtest &lt;mode&gt;</code></td><td>见下表</td></tr><tr><td><code>dumpinfo</code></td><td>核心转储缓冲状态</td><td>裸调用</td><td>大小 + 使用量</td></tr><tr><td><code>cryptotest</code></td><td>SHA-256 / AES-128 / HMAC-SHA256/384 + 堆金丝雀</td><td>裸调用</td><td>全部 PASS，不得出现 <code>DIFFERENT (memory corruption!)</code></td></tr><tr><td><code>dhtest</code></td><td>Diffie-Hellman</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>l1test</code></td><td>L1 作业/IPC/动态链接</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>nf_test</code></td><td>netfilter 规则（input drop、命中、移除后 ping 恢复）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>tcpcc_test</code></td><td>TCP 拥塞控制（CUBIC）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>tcptest</code></td><td>TCP 环回</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>dnstest</code></td><td>DNS 解析器测试组 + 内建向量</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>acpitest</code></td><td>ACPI 解析器（固定件表、<code>\\_S5</code> 求值、活动 DSDT）</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>i2ctest</code></td><td>I2C 控制器（i801/PIIX4、DesignWare）</td><td>裸调用</td><td>PASS 或如实的 <code>not present</code></td></tr><tr><td><code>smbustest</code></td><td>SMBus + NACK 视为错误检查</td><td>裸调用</td><td>PASS</td></tr><tr><td><code>touchtest</code></td><td>（见上文遗留端口）</td><td></td><td></td></tr></tbody></table><h3 id="自校验的-help-门-3" tabindex="-1">自校验的 help 门（3） <a class="header-anchor" href="#自校验的-help-门-3" aria-label="Permalink to &quot;自校验的 help 门（3）&quot;">​</a></h3><p>它们解析<strong>活动注册表文本本身</strong> —— 兼作注册表回归门 （如果某命令被意外从构建中遗漏，它们会在运行时失败， 而不只是 CI 中失败）：</p><table tabindex="0"><thead><tr><th>命令</th><th>断言</th></tr></thead><tbody><tr><td><code>help_default_test</code></td><td>默认列表的计数与形态</td></tr><tr><td><code>help_a_test</code></td><td><code>help -a</code> 输出严格 A-Z 有序</td></tr><tr><td><code>help_wp_test</code></td><td><code>help -w</code> 将每条目归入工作包头之下</td></tr></tbody></table><h3 id="live-fix-探针-1" tabindex="-1">live-fix 探针（1） <a class="header-anchor" href="#live-fix-探针-1" aria-label="Permalink to &quot;live-fix 探针（1）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>功能</th><th>运行</th></tr></thead><tbody><tr><td><code>p2test</code></td><td>三个定向探针之一，由 <code>tools/wp_p2_batch_a_test.py</code> 经 QEMU 串口控制台驱动</td><td><code>p2test utf8</code> 将 174 个汉字（522 字节，一次系统调用）推过两条写路径；<code>p2test read0</code> 检查 POSIX <code>read(0,buf,0)==0</code>；<code>p2test pipe</code> 连击管道槽复用 100 轮。失败串：<code>UTF8-FAIL short write</code>、<code>READ0-FAIL</code>、<code>PIPE-FAIL round=&lt;n&gt;</code></td></tr></tbody></table><hr><h2 id="msitest-—-msi-真实注入-op-21-diag-服务" tabindex="-1">msitest — MSI 真实注入（op 21，diag 服务） <a class="header-anchor" href="#msitest-—-msi-真实注入-op-21-diag-服务" aria-label="Permalink to &quot;msitest — MSI 真实注入（op 21，diag 服务）&quot;">​</a></h2><p><code>msitest</code> 是唯一会在<strong>你的真实硬件上触发真实中断</strong>的桩。 三个步骤，按序执行（<code>svc_diag_l1.c</code>）：</p><ol><li><strong>LAPIC 存在性 + self-IPI</strong> — 在向量 0x50 上注册处理程序， 经确切的消息写路径发送 self-IPI，短暂自旋， 然后比较向量计数器：<code>self-IPI vector 0x50: fired N time(s) PASS</code>。</li><li><strong>MSI 能力设备普查</strong> — 遍历 PCIe 设备列表统计 <code>cap_msi || cap_msix</code>：<code>MSI-capable devices: N of M</code>。</li><li><strong>真实触发</strong> — 找到第一块 e1000，在向量 0x51 上武装 MSI， 启用设备，然后向 Interrupt Cause Set 寄存器（BAR0 + 0x00C8）写入 <code>0xFFFFFFFF</code> 以一次性强制 <strong>所有</strong>中断原因。必须落下一次真正的 MSI 消息写：<code>e1000 MSI fire (ICS-&gt;MSI): fired N time(s) PASS</code>。随后解除 MSI 并 注销向量。无 e1000 或无 MSI 能力/BAR0 → <code>SKIP (reported honestly)</code>。</li></ol><p>最终判定：<code>msitest: PASS</code> / <code>msitest: FAIL</code>。若步骤 3 失败而 步骤 1-2 通过，则是 MSI 路由（而非 LAPIC）损坏 —— 先查 <code>pcibars</code> 的 BAR0 映射与 <code>pcie</code> 的链路状态。</p><hr><h2 id="b-类-—-平坦-ring-3-探针-24" tabindex="-1">B 类 — 平坦 ring-3 探针（24） <a class="header-anchor" href="#b-类-—-平坦-ring-3-探针-24" aria-label="Permalink to &quot;B 类 — 平坦 ring-3 探针（24）&quot;">​</a></h2><p><code>ocos/l1apps/</code> 下的单文件程序，直接演练内核面。 全部已注册；全部裸运行。（其余 <code>l1</code> 标签的程序 —— <code>ush</code>、<code>ld_so</code>、<code>ldd</code>、<code>l1test</code> —— 是 shell、 动态加载器本身、其列表器、以及作业/IPC 自测， 不是探针；<code>l1test</code> 已列在上文诊断家族中。）</p><h3 id="内核面探针-17" tabindex="-1">内核面探针（17） <a class="header-anchor" href="#内核面探针-17" aria-label="Permalink to &quot;内核面探针（17）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>探测内容</th><th>预期</th></tr></thead><tbody><tr><td><code>fork_test</code></td><td>fork/wait4 往返</td><td>子进程退出被收割，PASS</td></tr><tr><td><code>exec_test</code></td><td>execve 替换镜像</td><td>出现被 exec 程序的输出</td></tr><tr><td><code>fdref_test</code></td><td>dup/fork 间的 fd 引用计数</td><td>close 语义正确</td></tr><tr><td><code>pipe_test</code></td><td>管道写/读</td><td>字节往返</td></tr><tr><td><code>select_test</code></td><td>对就绪 fd 的 select</td><td>就绪判定正确</td></tr><tr><td><code>select_zero_test</code></td><td>零 fd 的 select</td><td>立即返回，不挂起</td></tr><tr><td><code>signal_test</code></td><td>信号投递 + 处理程序</td><td>处理程序运行，进程继续</td></tr><tr><td><code>sigsegv_test</code></td><td>SIGSEGV 遏制</td><td><code>*** SIGSEGV delivered to pid=N ... kernel continues ***</code>，进程被杀或处理程序运行</td></tr><tr><td><code>sse_test</code></td><td>切换间的 SSE 上下文</td><td>FP 值保持不变</td></tr><tr><td><code>stackovf</code></td><td>故意的用户栈溢出</td><td>进程被杀，内核继续</td></tr><tr><td><code>int3_user</code></td><td>ring-3 #BP</td><td>被遏制，内核继续</td></tr><tr><td><code>priv_test</code></td><td>ring 3 中的特权指令</td><td>#GP 投递给进程，内核继续</td></tr><tr><td><code>pf_test</code></td><td>ring-3 缺页</td><td>被遏制</td></tr><tr><td><code>p3_test</code></td><td>优先级调度</td><td>顺序符合优先级</td></tr><tr><td><code>mmap_test</code></td><td>mmap 基础</td><td>已映射、可读、已解除映射</td></tr><tr><td><code>mmap_multi</code></td><td>同时多重映射</td><td>全部相互独立</td></tr><tr><td><code>mprotect_test</code></td><td>mprotect W^X 强制</td><td>写只读页触发缺页</td></tr></tbody></table><h3 id="进程组-动态链接探针-7-固定件" tabindex="-1">进程组 / 动态链接探针（7 + 固定件） <a class="header-anchor" href="#进程组-动态链接探针-7-固定件" aria-label="Permalink to &quot;进程组 / 动态链接探针（7 + 固定件）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>探测内容</th><th>预期</th></tr></thead><tbody><tr><td><code>g6_test</code></td><td>G6 里程碑链（fork/exec/kill/oom），异步汇总</td><td><code>failed tests = 0</code></td></tr><tr><td><code>g6_exec_a</code> / <code>g6_exec_b</code></td><td>g6_test 驱动的两个 exec 半部</td><td>两半的输出</td></tr><tr><td><code>g6_oom</code></td><td>OOM 路径（地址空间清理）</td><td>进程干净死亡，内核存活</td></tr><tr><td><code>g7mmap</code></td><td>G7 mmap 里程碑（BUG-0281）</td><td>PASS</td></tr><tr><td><code>pie_test</code></td><td>PIE 程序加载</td><td><code>loaded at 0x...</code></td></tr><tr><td><code>reloc_test</code></td><td>重定位已施加</td><td><code>foo_add=30 foo_global=42 fp=300</code></td></tr><tr><td><code>so_test</code> / <code>dlsym_test</code> / <code>dyn_hello</code> / <code>main_dyn</code></td><td>solib 调用、dlsym、动态 hello、动态 main</td><td><code>foo_add(2,3)=5</code>、<code>foo_add(7,8)=15</code>、<code>hello from dynamic program</code></td></tr><tr><td><code>hello</code> / <code>loop</code> / <code>badapp</code> / <code>p0leak</code></td><td>固定件：hello world；空闲循环（作业目标）；故意行为不端者；用户指针围栏（<code>all kernel-address probes fenced</code>）</td><td>如所述</td></tr></tbody></table><hr><h2 id="crashtest-—-8-种故意失败模式" tabindex="-1">crashtest — 8 种故意失败模式 <a class="header-anchor" href="#crashtest-—-8-种故意失败模式" aria-label="Permalink to &quot;crashtest — 8 种故意失败模式&quot;">​</a></h2><p><code>crashtest &lt;mode&gt;</code> 注入一次特定崩溃，以便你观察完整的 WP-11 恢复路径（转储 + crashlog + klog 刷写 + 策略）。可以通过 裸命令或 <code>sysdiag</code> classic/direct 分发触达 —— <strong>刻意不设为 向导按钮</strong>（&quot;为故意 panic 注入设一个向导按钮是个坑&quot;）。</p><table tabindex="0"><thead><tr><th>模式</th><th>行为</th><th>应当看到</th></tr></thead><tbody><tr><td><code>panic</code></td><td>直接调用 <code>kernel_panic()</code></td><td><code>*** KERNEL PANIC: manual crashtest: kernel_panic() ***</code> + 寄存器 + 回溯 + 策略行</td></tr><tr><td><code>exc</code></td><td>执行一条 ring-0 #UD</td><td>异常横幅，随后 panic 路径；<code>crashtest: #UD returned unexpectedly</code> 表示故障未被触发 —— 本身即失败</td></tr><tr><td><code>pf</code></td><td>在 ring 0 写未映射地址</td><td><code>ring-0 exception 14 (#PF Page Fault)</code> panic</td></tr><tr><td><code>assert</code></td><td><code>OC_ASSERT(0)</code></td><td>panic 原因 <code>assertion failed: 0</code></td></tr><tr><td><code>wd</code></td><td>强制软件 watchdog 超时（武装 + 心跳回拨）</td><td><code>watchdog timeout: ...</code> panic</td></tr><tr><td><code>ovf</code></td><td>孵化一个逐帧增长 4 KiB 直至守卫页的 kthread</td><td><code>KERNEL STACK OVERFLOW (guard page hit, task=...)</code> panic</td></tr><tr><td><code>dump</code></td><td><code>core_dump_save(&quot;manual crashtest dump&quot;)</code> — 不 panic</td><td>转储已写入；启动期缓冲缺失时 <code>crashtest: dump FAILED (no boot-time buffer)</code></td></tr><tr><td><code>policy halt|reboot</code></td><td>设置 panic 后动作</td><td><code>crashtest: policy set - after the next panic the kernel will HALT</code></td></tr></tbody></table><p>未知变体打印 <code>crashtest: unknown variant &#39;&lt;v&gt;&#39; (try: crashtest help)</code>。任意 panic 模式之后，验证记录已落盘：<code>crashlog</code> （32 槽环形）、<code>dumpinfo</code>（核心转储缓冲）、<code>dmesg</code>（klog FATAL 行），以及文件系统上的 <code>/var/log/crash.log</code> + <code>/var/crash/core.dump</code>。</p><h2 id="从脚本运行桩" tabindex="-1">从脚本运行桩 <a class="header-anchor" href="#从脚本运行桩" aria-label="Permalink to &quot;从脚本运行桩&quot;">​</a></h2><p>每个桩都是普通命令，因此通常的 shell 特性都适用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; memtest &gt; /tmp/mem.txt</span></span>
<span class="line"><span>ush&gt; run dnstest</span></span>
<span class="line"><span>ush&gt; sysdiag direct memtest        # the mega-app verbatim door</span></span>
<span class="line"><span>ush&gt; logcat -k msitest -f          # follow only msitest&#39;s klog lines</span></span></code></pre></div><p>E2E 套件在串口控制台上做的正是这些（见 <a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a>）；逐应用记录 （<code>tools/run_l1_per_app.py</code>）为每个程序启动一次 ISO 并通过 <code>run &lt;name&gt;</code> 运行它。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./function-dictionary.html">function-dictionary.md</a> — 全部 296 条命令</li><li><a href="./../troubleshooting/error-codes.html">../troubleshooting/error-codes.md</a> — 桩输出中错误代码的含义</li><li><a href="./../troubleshooting/silent-failures.html">../troubleshooting/silent-failures.md</a> — 为何桩可能&quot;通过&quot;而功能已损坏（honest-skip 与 FAIL 之辨）</li></ul>`,55)])])}const _=d(r,[["render",a]]);export{S as __pageData,_ as default};
